<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([$id,actor_id()]);redirect('notifications.php');}$q=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100');$q->execute([actor_id()]);page_top('Notifications');?><div class='card p-3'><?php foreach($q as $n):?><div class='d-flex justify-content-between align-items-start p-3 border-bottom <?=($n['is_read']?'':'bg-light')?>'><div><strong><?=e($n['title'])?></strong><div><?=e($n['message'])?></div><small class='text-muted'><?=e($n['created_at'])?></small></div><?php if(!$n['is_read']):?><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='id' value='<?=e($n['id'])?>'><button class='btn btn-sm btn-outline-primary'>Mark read</button></form><?php endif;?></div><?php endforeach;?><?php if(!$q->rowCount()):?><div class='p-5 text-center text-muted'>No notifications.</div><?php endif;?></div><?php page_bottom(); ?>